from calc1_core import *
D=CalcDoc('2.7',[181,182,183,184,185],lambda n:181 if n<=5 else 182 if n<=18 else 183 if n<=27 else 184 if n<=36 else 185)
t=s.symbols('t',real=True)
def same(v):return(d(v),d(v))
def add(n,st,steps,ans,ck,parts=()):return D.add(n,('과학에서의 변화율','Rates of change in the sciences'),st,('변화하는 양과 독립변수의 단위를 정하고 미분한다. 운동은 속도·가속도의 부호,자료는 국소 차분 또는 명시한 회귀로 해석한다.','Identify the varying quantity and the independent variable with their units. For motion use velocity and acceleration signs;for data use local differences or an explicitly specified regression.'),steps,ans,ck,parts)
functions={1:t**3-9*t*t+24*t,2:t**4/100-t**3/25,3:s.sin(s.pi*t/2),4:9*t/(t*t+9)}
motion={1:([0,2,4,6],44,r't=2,4',r'0\le t<2\text{ or }t>4',('증속:(2,3)∪(4,∞);감속:(0,2)∪(3,4).','Speeding up:(2,3)∪(4,∞);slowing down:(0,2)∪(3,4).')),2:([0,3,6],s.Rational(243,50),r't=0,3',r't>3',('증속:(0,2)∪(3,∞);감속:(2,3).','Speeding up:(0,2)∪(3,∞);slowing down:(2,3).')),3:([0,1,3,5,6],6,r't=1+2k,\ k=0,1,2,\ldots',r'4k-1<t<4k+1,\ k\in\mathbb Z,\ t\ge0',('k=0,1,…에 대해 증속:(1+2k,2+2k);감속:(2k,1+2k).','For k=0,1,…,speeding up:(1+2k,2+2k);slowing down:(2k,1+2k).')),4:([0,3,6],s.Rational(9,5),r't=3',r'0\le t<3',('증속:(3,3√3);감속:(0,3)∪(3√3,∞).','Speeding up:(3,3√3);slowing down:(0,3)∪(3√3,∞).'))}
for n,f in functions.items():
 v=s.factor(s.diff(f,t));a=s.factor(s.diff(v,t));ts,dist,rest,positive,speed=motion[n];vals=[s.simplify(f.subs(t,z))for z in ts]
 st=('위치 '+m('s(t)='+tex(f))+',t≥0이며 t는초,s는ft이다. (a)v(t),(b)v(1),(c)정지 시각,(d)양의 방향 이동 구간,(e)처음6초 총거리,(f)방향을 표시한 운동 도해,(g)a(t),a(1),(h)0≤t≤6에서 s,v,a 그래프,(i)증속·감속 구간을 구하라.','For position '+m('s(t)='+tex(f))+',t≥0 with t in seconds and s in feet,find(a)v(t),(b)v(1),(c)rest times,(d)positive-motion intervals,(e)distance in the first6seconds,(f)a directed motion diagram,(g)a(t),a(1),(h)graphs of s,v,a on0≤t≤6,and(i)speeding-up/slowing-down intervals.')
 steps=[same(r'\text{(a),(b) }v=s\prime='+tex(v)+r',\quad v(1)='+tex(v.subs(t,1))+r'\ {\rm ft/s}'),same(r'\text{(c) }v=0\Rightarrow '+rest),same(r'\text{(d) }v>0\Rightarrow '+positive),same(r'\text{(e),(f) }(t,s):'+r'\longrightarrow'.join('('+str(z)+','+tex(val)+')'for z,val in zip(ts,vals))),same(r'D='+ '+'.join(r'\left|'+tex(vals[k+1])+'-('+tex(vals[k])+r')\right|'for k in range(len(vals)-1))+'='+tex(s.sympify(dist))+r'\ {\rm ft}'),same(r'\text{(g) }a=v\prime='+tex(a)+r',\quad a(1)='+tex(a.subs(t,1))+r'\ {\rm ft/s^2}'),('(h)아래 세 시간 그래프와 마지막 방향 도해를 참조한다. (i)v와 a의 부호가 같으면 속력 증가,다르면 감소이다. '+speed[0], '(h)See the three time graphs and final directed-motion diagram. (i)Speed increases when v and a have the same sign,and decreases when they have opposite signs. '+speed[1])]
 add(n,st,steps,(d('v='+tex(v)+r',\quad a='+tex(a)+r',\quad D_{0\to6}='+tex(s.sympify(dist)))+' '+speed[0],d('v='+tex(v)+r',\quad a='+tex(a)+r',\quad D_{0\to6}='+tex(s.sympify(dist)))+' '+speed[1]),('방향 전환 시각에서 구간을 나누어 위치 차의 절댓값을 더했다. 속력의 증가·감소는 도함수 va의 부호로 독립 확인했다.','Split the interval at direction changes and summed absolute position changes. Checked speeding up/slowing down through the sign of va.'),list('abcdefghi'))
 panels=[]
 for expr,label in[(f,'Position s (ft)'),(v,'Velocity v (ft/s)'),(a,'Acceleration a (ft/s^2)')]:
  pts=samples(s.lambdify(t,expr,'math'),0,6,600);ys=[p[1]for p in pts];span=max(ys)-min(ys);panels.append(panel(label,(0,6,min(ys)-.12*span,max(ys)+.12*span),[pts],xticks=list(range(7)),xlabel='t (s)',ylabel=''))
 D.fig(n,panels)
 # Append an actual directed displacement diagram, one leg per row.
 path=ROOT/'exercise-content/assets'/f's2-7-{n}.svg';svg=path.read_text();base=1110;extra=100+55*(len(ts)-1);svg=svg.replace('viewBox="0 0 640 1110"',f'viewBox="0 0 640 {base+extra}"').replace('height="1110"','height="'+str(base+extra)+'"');mn,mx=min(map(float,vals)),max(map(float,vals));X=lambda z:110+390*(float(z)-mn)/(mx-mn)
 chunk=f'<g font-family="Arial" font-size="14"><text x="30" y="{base+30}">Directed motion: each row is one time interval</text><defs><marker id="arrow" markerWidth="7" markerHeight="7" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6" fill="#1d4ed8"/></marker></defs>'
 for j in range(len(ts)-1):
  yy=base+70+55*j;chunk+=f'<text x="20" y="{yy}">t={ts[j]} to {ts[j+1]}</text><path d="M{X(vals[j])},{yy} H{X(vals[j+1])}" stroke="#1d4ed8" stroke-width="2" marker-end="url(#arrow)"/><text x="{X(vals[j])}" y="{yy-7}" text-anchor="middle">{float(vals[j]):g}</text><text x="{X(vals[j+1])}" y="{yy+20}" text-anchor="middle">{float(vals[j+1]):g} ft</text>'
 path.write_text(svg.replace('</svg>',chunk+'</g></svg>'))
# Graph-reading problems5–8 are added after independent source cross-reading.
add(9,('발사체 높이는 h(t)=2+24.5t−4.9t² m이다. (a)2초와4초 속도,(b)최고점 시각,(c)최대 높이,(d)지면 도착 시각,(e)도착 속도를 구하라.','A projectile has height h(t)=2+24.5t−4.9t² m. Find(a)velocity at2and4seconds,(b)time of maximum height,(c)maximum height,(d)ground-impact time,and(e)impact velocity.'),[same(r'v=24.5-9.8t,\quad v(2)=4.9,\ v(4)=-14.7\ {\rm m/s}'),same(r'v=0\Rightarrow t=2.5\ {\rm s},\quad h(2.5)=32.625\ {\rm m}'),same(r'h=0\Rightarrow t=\frac{24.5+\sqrt{639.45}}{9.8}\approx5.080\ {\rm s}'),same(r'v_{\rm impact}=-\sqrt{639.45}\approx-25.287\ {\rm m/s}')],('(a)4.9,−14.7 m/s;(b)2.5초;(c)32.625 m;(d)약5.080초;(e)약−25.287 m/s.','(a)4.9,−14.7 m/s;(b)2.5s;(c)32.625m;(d)about5.080s;(e)about−25.287m/s.'),('양의 충돌 시각만 택했다. v²=24.5²+2(9.8)(2)=639.45로 충돌 속력을 확인했다.','Selected the positive impact time. The identity v²=24.5²+2(9.8)(2)=639.45 checks the impact speed.'),list('abcde'))
add(10,('위로 던진 공의 높이는 s=80t−16t² ft이다. (a)최대 높이,(b)높이96ft에서 올라갈 때와 내려갈 때의 속도를 구하라.','A ball has height s=80t−16t² ft. Find(a)maximum height and(b)velocities at height96ft on the way up and down.'),[same(r'v=80-32t=0\Rightarrow t=2.5,\quad s=100\ {\rm ft}'),same(r'80t-16t^2=96\Rightarrow(t-2)(t-3)=0'),same(r'v(2)=16,\quad v(3)=-16\ {\rm ft/s}')],('(a)100ft;(b)상승16ft/s,하강−16ft/s.','(a)100ft;(b)upward16ft/s,downward−16ft/s.'),('두 높이가 모두96ft인지 대입하고 속도 부호로 상승·하강을 구별했다.','Substituted both times to recover96ft and used velocity signs to distinguish ascent and descent.'),list('ab'))
add(11,('화성에서 돌의 높이 h=15t−1.86t² m이다. (a)2초 후 속도,(b)높이25m를 지나는 상승·하강 속도를 구하라.','On Mars a rock has height h=15t−1.86t² m. Find(a)velocity after2seconds and(b)ascent/descent velocities at25m.'),[same(r'v=15-3.72t,\quad v(2)=7.56\ {\rm m/s}'),same(r'v^2=15^2-2(3.72)h'),same(r'h=25\Rightarrow v^2=39\Rightarrow v=\pm\sqrt{39}')],d(r'\text{(a) }7.56\ {\rm m/s};\quad\text{(b) }\sqrt{39}\approx6.245,\ -\sqrt{39}\approx-6.245\ {\rm m/s}'),('식 v²=225−7.44h는 주어진 h와v를 직접 대입해 얻으며,상승은 양수·하강은 음수이다.','The identity v²=225−7.44h follows by direct substitution;choose positive for ascent and negative for descent.'),list('ab'))
add(12,('위치 s=t⁴−4t³−20t²+20t,t≥0인 입자에 대해 (a)속도가20m/s인 시각,(b)가속도가0인 시각과 의미를 구하라.','For s=t⁴−4t³−20t²+20t,t≥0,find(a)when velocity is20m/s and(b)when acceleration is zero,with its significance.'),[same(r'v=4t^3-12t^2-40t+20'),same(r'v=20\Rightarrow4t(t-5)(t+2)=0\Rightarrow t=0,5'),same(r'a=12t^2-24t-40=0\Rightarrow t=1+\sqrt{39}/3\approx3.082'),('유효한 가속도 영점에서 a는 음수에서 양수로 바뀌어 속도가 최소가 된다. 위치 그래프의 오목·볼록도 바뀐다.','At the admissible acceleration zero,a changes from negative to positive,so velocity is minimal and the position graph changes concavity.')],d(r'\text{(a) }t=0,5;\quad\text{(b) }t=1+\sqrt{39}/3\approx3.082'),('t≥0 조건으로 음의 근−2와1−√39/3을 제외했다. 가속도 부호를 양쪽에서 확인했다.','Excluded negative roots−2 and1−√39/3 and checked acceleration signs on either side.'),list('ab'))
add(5,('원본 속도그래프(a)는 t≈1에서 극대,2에서 영점을 지나3까지 감소한다. (b)는 t≈1에서 양의 극소,2에서 양의 극대,3에서 영점을 지나4까지 감소한다. 각 입자의 증속·감속 구간을 설명하라.','Source velocity graph(a)peaks near t=1,crosses zero at2,and decreases to3. Graph(b)has a positive local minimum near1,a positive local maximum near2,and crosses zero at3 before decreasing to4. Explain the speeding-up and slowing-down intervals.'),[('속도그래프의 높이는 v,기울기는 a이다. 같은 부호면 속력이 증가하고 반대 부호면 감소한다.','The graph height is v and its slope is a. Equal signs increase speed;opposite signs decrease it.'),('(a)0–1에서는 v,a>0;1–2에서는 v>0,a<0;2–3에서는 v,a<0이다.','(a)On0–1,v,a>0;on1–2,v>0,a<0;on2–3,v,a<0.'),('(b)0–1은 양의 속도가 감소,1–2는 증가,2–3은 감소한다.3–4는 음의 속도가 더 음수가 된다.','(b)The positive velocity decreases on0–1,increases on1–2,and decreases on2–3. On3–4 negative velocity becomes more negative.')],('(a)증속(0,1)∪(2,3),감속(1,2). (b)증속(1,2)∪(3,4),감속(0,1)∪(2,3). 경계는 그래프 판독 근사이다.','(a)Speeding up(0,1)∪(2,3),slowing down(1,2). (b)Speeding up(1,2)∪(3,4),slowing down(0,1)∪(2,3). Boundaries are graphical estimates.'),('원본의 가로 눈금을 독립적으로 두 번 읽었다. 아래 그림은 부호와 전환 순서를 보존한 자체 예시이며 원본의 정확한 함수식을 주장하지 않는다.','The source time marks were independently read twice. The native sketches preserve signs and transition order without asserting an exact source formula.'),list('ab'))
D.fig(5,[panel('(a) Qualitative velocity sketch',(0,3,-3.2,1.3),[samples(lambda z:z*(2-z),0,3)],xticks=[0,1,2,3],xlabel='t',ylabel='v'),panel('(b) Qualitative velocity sketch',(0,4,-4,2),[samples(lambda z:-z**3/3+1.5*z*z-2*z+1.5,0,4)],xticks=[0,1,2,3,4],xlabel='t',ylabel='v')],caption=('원본의 부호·극값·영점 순서를 보존한 정성 재구성. 세로 크기는 예시이다.','Qualitative reconstruction preserving source signs,extrema,and zero order;vertical magnitudes are illustrative.'))
add(6,('원본 위치그래프(a)는 약 t=1에서 극대,3에서 극소,2에서 변곡한다. (b)는0–3에서 감소하고3–4에서 증가하며 약1,2에서 오목·볼록이 바뀐다. 각각 속도가 양수·음수인 구간과 증속·감속 구간을 구하라.','Source position graph(a)has a maximum near t=1,a minimum near3,and an inflection near2. Graph(b)decreases on0–3,increases on3–4,and changes concavity near1and2. Find positive/negative velocity and speeding-up/slowing-down intervals.'),[('위치의 기울기 s′가 속도이고 오목·볼록을 나타내는 s″가 가속도이다.','The slope s′ gives velocity and the concavity s″ gives acceleration.'),('(a)v>0:(0,1)∪(3,4),v<0:(1,3). (b)v<0:(0,3),v>0:(3,4).','(a)v>0 on(0,1)∪(3,4),v<0 on(1,3). (b)v<0 on(0,3),v>0 on(3,4).'),('두 그림 모두1–2에서는 음의 속도와 음의 가속도,3–4에서는 양의 속도와 양의 가속도를 가진다.0–1과2–3에서는 부호가 반대이다.','Both graphs have negative velocity and acceleration on1–2,and positive velocity and acceleration on3–4. Their signs are opposite on0–1 and2–3.')],('(a)v>0:(0,1)∪(3,4),v<0:(1,3);(b)v>0:(3,4),v<0:(0,3). 둘 다 증속(1,2)∪(3,4),감속(0,1)∪(2,3).','(a)v>0:(0,1)∪(3,4),v<0:(1,3);(b)v>0:(3,4),v<0:(0,3). Both speed up on(1,2)∪(3,4) and slow down on(0,1)∪(2,3).'),('변곡 시각은 원본 곡선의 근삿값이다. 자체 도해는 단조성·오목성 전환만 보존하며 정확한 위치식이 아니다.','Inflection times are estimates from the source. The native sketches preserve monotonicity and concavity transitions,not an exact position formula.'),list('ab'))
def pos6a(z):return 3*z-1.5*z*z if z<=1 else 1.5-.9*(z-1)**2+.3*(z-1)**3 if z<=3 else .3+1.7*(z-3)**2
def pos6b(z):return -.6*(z-2)-1.4/3*((z-1)**3-1)if z<=2 else -2*(z-2)+2/3*(z-2)**3 if z<=3 else -4/3+4/3*(z-3)**2
D.fig(6,[panel('(a) Qualitative position sketch',(0,4,-.2,2.2),[samples(pos6a,0,4)],xticks=[0,1,2,3,4],xlabel='t',ylabel='s'),panel('(b) Qualitative position sketch',(0,4,-1.6,2.4),[samples(pos6b,0,4)],xticks=[0,1,2,3,4],xlabel='t',ylabel='s')],caption=('독립 판독한 증감·오목성 전환을 보여 주는 자체 정성 도해.','Native qualitative sketches showing the independently read monotonicity and concavity transitions.'))
verts=[(0,0),(1,3),(3,3),(5,0),(7,0),(8,-3)]
add(7,('속도그래프는(0,0),(1,3),(3,3),(5,0),(7,0),(8,−3)을 순서대로 잇는 선분이다. t는초이다. 전진·후진 구간과5<t<7의 상태를 설명하라.','The velocity graph joins(0,0),(1,3),(3,3),(5,0),(7,0),(8,−3) by straight segments,with t in seconds. Identify forward/backward motion and explain the state for5<t<7.'),[('0<t<5에서는 v>0이므로 전진한다.7<t≤8에서는 v<0이므로 후진한다.','Velocity is positive for0<t<5,so motion is forward;it is negative for7<t≤8,so motion is backward.'),('5≤t≤7에는 v=0이므로 위치가 일정하며 정지한다. 원점 t=0에서도 순간 속도는0이다.','On5≤t≤7,velocity is zero,so position is constant and the particle rests. Instantaneous velocity is also zero at t=0.')],('전진0<t<5;후진7<t≤8;5≤t≤7에는 정지.','Forward:0<t<5;backward:7<t≤8;at rest on5≤t≤7.'),('높이의 부호로 방향을 판정했고 기울기와 혼동하지 않았다.','Used the sign of the graph height for direction rather than its slope.'))
D.fig(7,[panel('Source grid reconstructed from vertices',(0,8,-3.5,3.5),[verts],xticks=list(range(9)),yticks=list(range(-3,4)),xlabel='t (s)',ylabel='v')])
add(8,('속도그래프가(0,0),(1,3),(3,3),(5,0),(7,0),(8,−3)을 선분으로 이을 때 가속도 그래프를 그리고 증속·감속·일정 속력 구간을 구하라.','For the piecewise-linear velocity graph through(0,0),(1,3),(3,3),(5,0),(7,0),(8,−3),plot acceleration and find intervals of increasing,decreasing,and constant speed.'),[same(r'a(t)=\begin{cases}3&0<t<1\\0&1<t<3\\-3/2&3<t<5\\0&5<t<7\\-3&7<t<8\end{cases}'),('t=1,3,5,7에서 속도그래프가 꺾여 가속도는 정의되지 않는다.','Acceleration is undefined at the velocity corners t=1,3,5,7.'),('증속은 v,a가 같은 부호인0–1과7–8,감속은 양의v와 음의a를 갖는3–5이다.','Speed increases on0–1 and7–8 where v,a have the same sign;it decreases on3–5 where v>0,a<0.')],('증속(0,1)∪(7,8);감속(3,5);일정 속력[1,3](속력3)과[5,7](속력0). 가속도는 각 열린 구간에서3,0,−1.5,0,−3.','Speeding up:(0,1)∪(7,8);slowing down:(3,5);constant speed on[1,3](speed3) and[5,7](speed0). Acceleration on successive open intervals is3,0,−1.5,0,−3.'),('각 가속도는 인접 두 꼭짓점의 Δv/Δt이며 총속도변화3−3−3=−3과 끝점 차가 같다.','Each acceleration is Δv/Δt between adjacent vertices;the total velocity change3−3−3=−3 agrees with the endpoint difference.'))
segs=[(0,1,3),(1,3,0),(3,5,-1.5),(5,7,0),(7,8,-3)];D.fig(8,[panel('Acceleration; open endpoints at velocity corners',(0,8,-3.5,3.5),[[(a,v),(b,v)]for a,b,v in segs],[(a,v,'open')for a,b,v in segs]+[(b,v,'open')for a,b,v in segs],xticks=list(range(9)),xlabel='t (s)',ylabel='a')])
add(13,('정사각형 웨이퍼의 한 변 x와 면적 A(x)에 대해 (a)A′(15)를 구하고 단위를 포함해 뜻을 설명하라(x:mm). (b)A′가 둘레의 절반임을 보이고 변의 증가Δx에 대한 그림으로 작은 면적 변화ΔA를 근사하라.','For a square wafer with side x mm and area A(x),(a)find and interpret A′(15) with units. (b)Show A′ is half the perimeter and draw the increase by Δx to approximate the small area change ΔA.'),[same(r'A=x^2,\quad A\prime=2x,\quad A\prime(15)=30\ {\rm mm^2/mm}'),('변 길이가15mm 부근에서1mm 증가할 때 면적은 국소적으로 약30mm²씩 증가한다. 작은 Δx에는 ΔA≈30Δx이다.','Near15mm,a unit increase in side length corresponds locally to about30mm² per mm;for small Δx,ΔA≈30Δx.'),same(r'\Delta A=(x+\Delta x)^2-x^2=2x\Delta x+(\Delta x)^2\approx2x\Delta x'),('그림의 폭Δx인 두 띠가 주된 증가이고 모서리의 작은 정사각형은2차항이다. 따라서 dA/dx=2x는 둘레4x의 절반이다.','Two strips of width Δx give the leading increase;the tiny corner square is second order. Thus dA/dx=2x is half the perimeter4x.')],d(r'A\prime(15)=30\ {\rm mm^2/mm};\quad A\prime=2x=\tfrac12(4x);\quad\Delta A\approx2x\Delta x'),('정확한 증가식과 근사식의 차는(Δx)²이므로 Δx로 나눈 오차는0으로 간다.','The exact-minus-approximate error is(Δx)²,so the error divided by Δx tends to zero.'),list('ab'))
add(14,('한 변이 x mm인 정육면체 결정의 부피 V에 대해 (a)x=3에서 dV/dx를 계산·해석하고,(b)도함수가 표면적의 절반임을 기하적으로 설명하라.','For a cubic crystal with side x mm and volume V,(a)compute and interpret dV/dx at x=3,and(b)geometrically explain why it is half the surface area.'),[same(r'V=x^3,\quad dV/dx=3x^2,\quad V\prime(3)=27\ {\rm mm^3/mm}'),same(r'\Delta V=3x^2\Delta x+3x(\Delta x)^2+(\Delta x)^3'),('세 방향으로 두께Δx인 판이 추가되어 일차 부피가3x²Δx이다. 모서리와 꼭짓점의 중첩은2차 이상이다. 표면적은6x²이므로 도함수는 그 절반이다.','Three slabs of thickness Δx contribute leading volume3x²Δx;edge and corner contributions are higher order. Surface area is6x²,so the derivative is half that area.')],d(r'V\prime(3)=27\ {\rm mm^3/mm},\quad V\prime=3x^2=\tfrac12(6x^2)'),('변 길이의 작은 변화에 대해 ΔV≈27Δx(mm³)를 의미하며 부피/길이 단위를 유지한다.','For a small side change near3mm,the volume change is approximately27Δx mm³;units are volume per length.'),list('ab'))
add(15,('원의 면적 A=πr²에 대해 (a)r이2에서3,2.5,2.1로 바뀔 때 평균변화율,(b)r=2의 순간변화율,(c)일반 r의 도함수가 둘레임을 보이고 얇은 고리 그림으로 ΔA를 근사하라.','For A=πr²,(a)find average rates as r goes from2 to3,2.5,and2.1;(b)find the instantaneous rate at2;(c)show the derivative equals circumference and use a thin-annulus sketch to approximate ΔA.'),[same(r'\frac{A(b)-A(2)}{b-2}=\pi(b+2)\Rightarrow5\pi,\ 4.5\pi,\ 4.1\pi'),same(r'A\prime(r)=2\pi r,\quad A\prime(2)=4\pi'),same(r'\Delta A=2\pi r\Delta r+\pi(\Delta r)^2\approx2\pi r\Delta r'),('얇은 고리를 펼치면 길이2πr,폭Δr의 띠로 근사되므로 둘레가 면적의 반지름별 변화율이다.','Unrolling a thin annulus gives approximately a strip of length2πr and widthΔr,explaining why circumference is the area derivative.')],d(r'\text{(a) }5\pi,\ 9\pi/2,\ 41\pi/10;\quad\text{(b) }4\pi;\quad\text{(c) }A\prime=2\pi r,\ \Delta A\approx2\pi r\Delta r'),('평균변화율 π(4+Δr)는 Δr→0에서4π로 가며 기하적 근사와 일치한다.','The average rate π(4+Δr) tends to4π as Δr→0,agreeing with the geometric approximation.'),list('abc'))
add(16,('물결의 원형 경계가 반지름0에서60cm/s로 퍼진다. 내부 면적의 증가율을(a)1초,(b)3초,(c)5초에서 구하고 경향을 설명하라.','A circular ripple expands from radius zero at60cm/s. Find the enclosed-area growth rate after(a)1,(b)3,and(c)5seconds,and explain its trend.'),[same(r'r=60t,\quad A=\pi(60t)^2=3600\pi t^2'),same(r'dA/dt=7200\pi t')],d(r'7200\pi,\quad21600\pi,\quad36000\pi\ {\rm cm^2/s}'),('면적 증가율은 시간에 비례한다. 둘레2πr에 일정한 바깥쪽 속도60을 곱해도 같은 결과이다.','Area growth is proportional to time;circumference2πr times outward speed60 gives the same result.'),list('abc'))
add(17,('구형 풍선의 표면적 S=4πr²에 대해 반지름별 증가율 dS/dr를 (a)r=1ft,(b)2ft,(c)3ft에서 구하고 경향을 설명하라.','For a spherical balloon with S=4πr²,find dS/dr at(a)r=1ft,(b)2ft,and(c)3ft,and describe the trend.'),[same(r'dS/dr=8\pi r'),same(r'S\prime(1)=8\pi,\quad S\prime(2)=16\pi,\quad S\prime(3)=24\pi\ {\rm ft^2/ft}')],d(r'8\pi,\ 16\pi,\ 24\pi\ {\rm ft^2/ft};\quad dS/dr=8\pi r'),('이 변화율은 시간당이 아니라 반지름 길이당 면적 증가이며 r에 선형 비례한다.','This is area increase per radius length,not per time;it is linear in r.'),list('abc'))
add(18,('구형 세포의 V=(4/3)πr³,r의 단위μm이다. (a)r이5에서8,6,5.1로 바뀔 때 평균변화율,(b)r=5의 순간변화율,(c)일반 도함수가 표면적과 같음을 기하적으로 설명하라.','A spherical cell has V=(4/3)πr³ with r inμm. Find(a)average rates from5 to8,6,and5.1;(b)the instantaneous rate at5;and(c)geometrically explain why the general derivative equals surface area.'),[same(r'\frac{V(b)-V(5)}{b-5}=\frac{4\pi}3(b^2+5b+25)'),same(r'\text{(a) }172\pi,\quad364\pi/3,\quad7651\pi/75\ {\rm \mu m^3/\mu m}'),same(r'V\prime=4\pi r^2,\quad V\prime(5)=100\pi\ {\rm \mu m^2}'),('얇은 구껍질의 부피는 표면적4πr²와 두께Δr의 곱으로 근사된다. 정확한 증가식의 나머지는(Δr)²이상의 항이다.','A thin spherical shell has approximate volume equal to surface area4πr² times thicknessΔr. Remaining terms in the exact expansion have order(Δr)² or higher.')],d(r'\text{(a) }172\pi,364\pi/3,7651\pi/75;\quad\text{(b) }100\pi;\quad\text{(c) }V\prime=4\pi r^2'),('b=5.1은51/10으로 정확히 계산했다. 평균변화율은 b→5에서100π로 수렴한다.','Used exact b=51/10 for5.1. The average rate tends to100π as b→5.'),list('abc'))
add(19,('막대의 왼쪽 끝에서 x m까지 질량이 m(x)=3x² kg이다. 선밀도를 (a)x=1,(b)2,(c)3에서 구하고 가장 크고 작은 위치를 설명하라.','The mass from a rod’s left end to position x m is m(x)=3x² kg. Find linear density at(a)x=1,(b)2,(c)3,and locate its highest and lowest values.'),[same(r'\rho(x)=dm/dx=6x\ {\rm kg/m}'),same(r'\rho(1)=6,\quad\rho(2)=12,\quad\rho(3)=18'),('밀도는 오른쪽으로 갈수록 증가하므로 실제 막대의 오른쪽 끝에서 최대,왼쪽 끝에서 최소0이다. 주어진 세 점 중 최대는3m,최소는1m이다.','Density increases to the right,so it is greatest at the actual rod’s right end and least at the left end,value0. Among the three sampled points,it is greatest at3m and least at1m.')],d(r'6,12,18\ {\rm kg/m};\quad\rho(x)=6x'),('작은 구간의 질량 차3[(x+Δx)²−x²]를 Δx로 나눈 극한도6x이다. 막대의 전체 길이는 주어지지 않았다.','The mass difference3[(x+Δx)²−x²] divided by Δx also tends to6x. The full rod length is not supplied.'),list('abc'))
add(20,('탱크의 남은 물 V(t)=5000(1−t/40)² gal,0≤t≤40이며 t는분이다. 배출률을(a)5,(b)10,(c)20,(d)40분에서 구하고 가장 빠른·느린 시각을 설명하라.','A tank contains V(t)=5000(1−t/40)² gal for0≤t≤40 minutes. Find outflow at(a)5,(b)10,(c)20,(d)40minutes,and describe when it is fastest and slowest.'),[same(r'V\prime=-250(1-t/40),\quad Q_{\rm out}=-V\prime=250(1-t/40)'),same(r'Q_{\rm out}(5)=218.75,\ Q_{\rm out}(10)=187.5,\ Q_{\rm out}(20)=125,\ Q_{\rm out}(40)=0'),('배출률은0분의250gal/min에서40분의0까지 선형으로 감소한다. 남은 물의 변화율 V′는 그 음수이다.','Outflow decreases linearly from250gal/min at0minutes to0 at40minutes. The remaining-volume rate V′ has the opposite sign.')],('(a)218.75,(b)187.5,(c)125,(d)0 gal/min. 가장 빠름:t=0;가장 느림:t=40.','(a)218.75,(b)187.5,(c)125,(d)0gal/min. Fastest at t=0;slowest at t=40.'),('양의 배출량과 음의 저장량 변화율을 구별했다. 전체 배출량은 삼각형 넓이(1/2)·40·250=5000gal로 원래 용량과 같다.','Distinguished positive outflow from negative stored-volume change. Total outflow is the triangular area(1/2)·40·250=5000gal,matching capacity.'),list('abcd'))
add(21,('통과 전하 Q(t)=t³−2t²+6t+2 C,t는초이다. 전류를(a)0.5초,(b)1초에서 구하고 전류가 최소인 시각을 구하라.','Charge passing a point is Q(t)=t³−2t²+6t+2 C,with t in seconds. Find current at(a)0.5s,(b)1s,and when current is minimal.'),[same(r'I=Q\prime=3t^2-4t+6'),same(r'I(1/2)=19/4=4.75\ {\rm A},\quad I(1)=5\ {\rm A}'),same(r'I=3(t-2/3)^2+14/3')],d(r'\text{(a) }4.75\ {\rm A};\quad\text{(b) }5\ {\rm A};\quad t_{\min}=2/3\ {\rm s}'),('완전제곱 항이0인 t=2/3에서 전역 최소14/3A를 얻는다.','The square term vanishes at t=2/3,giving the global minimum14/3A.'),list('ab'))
add(22,('중력의 크기 F=GmM/r²에 대해 (a)dF/dr와 음수 부호의 의미를 설명하라. (b)r=20000km에서 변화율이−2N/km이면10000km에서 얼마인가?','For gravitational-force magnitude F=GmM/r²,(a)find and interpret dF/dr and its negative sign. (b)If the rate is−2N/km at20000km,find it at10000km.'),[same(r'dF/dr=-2GmM/r^3'),('거리가 증가하면 인력의 크기가 줄어든다는 뜻이며,물체가 움직이는 시간당 변화율과는 구별한다.','The magnitude of attraction decreases with increasing separation;this is distinct from change per unit time.'),same(r'F\prime(10000)=F\prime(20000)(20000/10000)^3=-2\cdot8=-16\ {\rm N/km}')],d(r'dF/dr=-2GmM/r^3;\quad\text{(b) }-16\ {\rm N/km}'),('힘은 r⁻²이지만 그 거리별 변화율은 r⁻³이므로 배율은4가 아니라8이다.','Force scales as r⁻²,but its radial derivative scales as r⁻³,so the factor is8.'),list('ab'))
add(23,('상대론적 질량 m=m₀/√(1−v²/c²),운동량 변화율 F=d(mv)/dt와 a=dv/dt를 이용하여 F=m₀a/(1−v²/c²)^(3/2)를 보여라(|v|<c).','Using relativistic mass m=m₀/√(1−v²/c²),force F=d(mv)/dt,and a=dv/dt,prove F=m₀a/(1−v²/c²)^(3/2),for|v|<c.'),[same(r'\frac{dm}{dt}=\frac{m_0va}{c^2(1-v^2/c^2)^{3/2}}'),same(r'F=ma+v\frac{dm}{dt}=\frac{m_0a(1-v^2/c^2)+m_0v^2a/c^2}{(1-v^2/c^2)^{3/2}}')],d(r'F=\frac{m_0a}{(1-v^2/c^2)^{3/2}}'),('분자의 두 v²/c²항이 상쇄되며 v/c→0에서 고전식 m₀a로 수렴한다.','The two v²/c² terms cancel;as v/c→0,the result tends to the classical m₀a.'))
vals24=[-2.515*math.sin(.503*(z-6.75))for z in[3,6,9,12]]
add(24,('자정 이후 t시간의 조수 깊이를 D(t)=7+5cos[0.503(t−6.75)] m로 모형화한다. (a)오전3시,(b)6시,(c)9시,(d)정오의 상승·하강 변화율을 구하라.','Tidal depth t hours after midnight is modeled by D(t)=7+5cos[0.503(t−6.75)] m. Find the rising/falling rates at(a)3AM,(b)6AM,(c)9AM,and(d)noon.'),[same(r'D\prime(t)=-2.515\sin[0.503(t-6.75)]'),same(r'(D\prime(3),D\prime(6),D\prime(9),D\prime(12))\approx('+','.join(f'{z:.4f}'for z in vals24)+r')\ {\rm m/h}')],(f'(a){vals24[0]:.4f},(b){vals24[1]:.4f}m/h로 상승;(c){vals24[2]:.4f},(d){vals24[3]:.4f}m/h로 하강.',f'(a){vals24[0]:.4f},(b){vals24[1]:.4f}m/h,rising;(c){vals24[2]:.4f},(d){vals24[3]:.4f}m/h,falling.'),('6.75시간이 만조이고 도함수는 그곳에서0이다. 지정 시각의 부호가 만조 전후의 움직임과 맞는지 확인했다.','The derivative vanishes at high tide t=6.75;the signs at the requested times agree with rising before and falling after high tide.'),list('abcd'))
add(25,('등온 보일 법칙 PV=C(C>0)에 대해 (a)dV/dP,(b)낮은 압력에서 시작해10분 동안 압력을 일정한 비율로 높일 때 부피가 처음과 끝 중 언제 더 빨리 줄어드는지,(c)등온 압축률 β=−(1/V)dV/dP를 구하라.','For Boyle’s isothermal law PV=C>0,(a)find dV/dP,(b)compare the volume-decrease rate at the beginning and end of10minutes of steady pressure increase from low pressure,and(c)find compressibility β=−(1/V)dV/dP.'),[same(r'V=C/P,\quad dV/dP=-C/P^2=-V/P'),('같은 압력 증가에 대한 부피 감소 크기 C/P²는 낮은 압력에서 더 크다. dP/dt가 일정하게 양수일 때 |dV/dt|=(C/P²)dP/dt도 처음이 더 크다.','The volume decrease per equal pressure increment,C/P²,is larger at low pressure. With constant positive dP/dt,|dV/dt|=(C/P²)dP/dt is also larger initially.'),same(r'\beta=-\frac1V\left(-\frac VP\right)=1/P')],d(r'\text{(a) }dV/dP=-C/P^2;\quad\text{(b) beginning};\quad\text{(c) }\beta=1/P'),('시간당 압력 증가율이 일정하다는 해석을 명시했다. 임의로 달라지는 가압 일정에는 시간당 부피 감소의 순서를 이 법칙만으로 정할 수 없다.','Made the steady pressure-rate interpretation explicit. With an arbitrary varying pressure schedule,Boyle’s law alone does not order the volume decreases per time.'),list('abc'))
add(26,('반응 A+B→C에서 초기 두 반응물 농도는 공통으로 a mol/L이다. 생성물 농도 x(t)=a²kt/(akt+1)에 대해(a)반응속도,(b)x′=k(a−x)²임을 구하고 보이라.','In A+B→C,both initial reactant concentrations are a mol/L. For product concentration x(t)=a²kt/(akt+1),(a)find the reaction rate and(b)show x′=k(a−x)².'),[same(r'x\prime=\frac{a^2k(akt+1)-a^2kt(ak)}{(akt+1)^2}=\frac{a^2k}{(akt+1)^2}'),same(r'a-x=\frac{a(akt+1)-a^2kt}{akt+1}=\frac a{akt+1}')],d(r'x\prime=\frac{a^2k}{(akt+1)^2}=k(a-x)^2'),('생성물 하나당 두 반응물을 하나씩 사용하므로 남은 농도 a−x를 제곱하는 식과 일치한다.','Each product molecule uses one molecule of each reactant,consistent with the product of remaining concentrations(a−x)².'),list('ab'))
# Exact least-squares normal equations, not interpolation or rounded-coefficient fits.
def regress(xs,ys,degree):
 X=s.Matrix([[s.Rational(z)**k for k in range(degree+1)]for z in xs]);Y=s.Matrix([s.Rational(str(z))for z in ys]);coef=(X.T*X).inv()*X.T*Y;assert X.T*(X*coef-Y)==s.zeros(degree+1,1);return sum(coef[k]*t**k for k in range(degree+1))
def decimal_tex(expr):return s.latex(s.Poly(expr,t).as_expr().evalf(11))
xs27=list(range(0,111,10));ys27=[1650,1750,1860,2070,2300,2560,3040,3710,4450,5280,6080,6870];p27=regress(xs27,ys27,3);dp27=s.diff(p27,t)
add(27,('1900년을 t=0으로 하는 세계 인구(백만명) 자료 t='+str(xs27)+',P='+str(ys27)+'가 주어진다. (a)1920·1980년 성장률을 양쪽 할선 기울기의 평균으로 추정하라. (b)3차 최소제곱 모형,(c)그 성장률 모형,(d)모형의1920·1980년 추정과(a)의 비교,(e)1985년 추정을 구하라.','World population(millions),with t=0 in1900,is given by t='+str(xs27)+',P='+str(ys27)+'. (a)Estimate growth in1920and1980 by averaging adjacent secant slopes. (b)Fit a cubic least-squares model,(c)differentiate it,(d)compare its1920/1980 estimates with(a),and(e)estimate growth in1985.'),[same(r'\text{(a) }P\prime(20)\approx\tfrac12[(1860-1750)/10+(2070-1860)/10]=16'),same(r'P\prime(80)\approx\tfrac12[(4450-3710)/10+(5280-4450)/10]=78.5'),('12개 자료의 수직 잔차 제곱합을 최소화하는3차 다항식을 적합한다.','Fit a cubic by minimizing the sum of squared vertical residuals for all12data points.'),same(r'\text{(b) }P(t)\approx'+decimal_tex(p27)),same(r'\text{(c) }P\prime(t)\approx'+decimal_tex(dp27)),same(r'\text{(d),(e) }P\prime(20)\approx14.1598,\quad P\prime(80)\approx71.7236,\quad P\prime(85)\approx76.2428'),('국소 할선 추정16,78.5에 비해 전체 구간 회귀 추정은 각각 약1.84,6.78백만명/년 작다. 모형은 모든 점을 보간하는 것이 아니다.','Relative to local estimates16and78.5,the global regression rates are lower by about1.84and6.78million/year. The model does not interpolate every point.')],('(a)16,78.5백만명/년;(d)14.1598,71.7236백만명/년;(e)76.2428백만명/년. 회귀식은 위(b),(c).','(a)16,78.5million/year;(d)14.1598,71.7236million/year;(e)76.2428million/year. Models are given in(b),(c)above.'),('회귀계수는 유리수 정상방정식으로 구해 Xᵀ(Xc−Y)=0을 정확히 확인했다. 미분값에는 반올림 전 계수를 사용했다.','Solved rational normal equations and verified Xᵀ(Xc−Y)=0 exactly. Evaluated derivatives using unrounded coefficients.'),list('abcde'))
xs28=list(range(1950,2016,5));ys28=[23,23.8,24.4,24.5,24.2,24.7,25.2,25.5,25.9,26.3,27,28,28.8,29.4];p28=regress([z-1950 for z in xs28],ys28,4);dp28=s.diff(p28,t)
add(28,('일본 여성의 평균 초혼연령 자료:연도 '+str(xs28)+',연령 '+str(ys28)+'. (a)4차 최소제곱 모형,(b)연령 변화율 모형,(c)1990년 변화율 추정,(d)자료와 두 모형 그래프를 구하라.','Japanese women’s average first-marriage ages are:years '+str(xs28)+',ages '+str(ys28)+'. Find(a)a quartic least-squares model,(b)its rate model,(c)the1990rate estimate,and(d)plots of the data and both models.'),[('u=연도−1950으로 놓는다. du/d(연도)=1이므로 단위를 바꾸지 않고 미분할 수 있다.','Set u=year−1950. Since du/d(year)=1,differentiation preserves the units.'),same(r'\text{(a) }A\approx'+decimal_tex(p28).replace('t','u')),same(r'\text{(b) }dA/dt\approx'+decimal_tex(dp28).replace('t','u')),same(r'\text{(c) }t=1990\Rightarrow u=40,\quad A\prime(1990)\approx0.108979795'),('(d)아래 그림에서 첫 패널은14개 자료점과4차 곡선,둘째는 그 도함수이다.','(d)The first panel plots all14data points and the quartic;the second plots its derivative.')],('(c)약0.1090연령년/달력년.4차 모형과 도함수는 위 식과 도해를 참조한다.','(c)About0.1090age-years per calendar year. The quartic and derivative are displayed above and plotted below.'),('중심화한 모든 자료로 정확한 정상방정식을 풀고 잔차가1,u,u²,u³,u⁴에 직교함을 확인했다.','Solved exact normal equations for all centered data and verified residual orthogonality to1,u,u²,u³,u⁴.'),list('abcd'))
D.fig(28,[panel('Marriage age: data and quartic',(1950,2015,22,30),[samples(lambda year:float(p28.subs(t,year-1950)),1950,2015,300)],list(zip(xs28,ys28)),xlabel='year',ylabel='age'),panel('Rate from the quartic',(1950,2015,-.02,.25),[samples(lambda year:float(dp28.subs(t,year-1950)),1950,2015,300)],xlabel='year',ylabel='age-years/year')])
add(29,('층류 속도 v(r)=P(R²−r²)/(4ηl)를 사용하라. R=0.01cm,l=3cm,P=3000dyn/cm²,η=0.027이다. (a)r=0,0.005,0.01cm의 속도,(b)같은 곳의 속도기울기 dv/dr,(c)속도 및 기울기 크기가 최대인 곳을 구하라.','Use laminar-flow velocity v(r)=P(R²−r²)/(4ηl),with R=0.01cm,l=3cm,P=3000dyn/cm²,η=0.027. Find(a)velocities at r=0,0.005,0.01cm,(b)velocity gradients there,and(c)where velocity and gradient magnitude are largest.'),[same(r'v(r)=\frac{3000}{4(0.027)(3)}(0.0001-r^2)=\frac{250000}{27}(0.0001-r^2)'),same(r'v(0)=25/27,\quad v(0.005)=25/36,\quad v(0.01)=0\ {\rm cm/s}'),same(r'v\prime(r)=-\frac{500000}{27}r'),same(r'v\prime(0)=0,\quad v\prime(0.005)=-2500/27,\quad v\prime(0.01)=-5000/27\ {\rm s^{-1}}'),('속도는 중심선 r=0에서 최대이고,변화율의 절댓값은 관벽 r=R에서 최대이다.','Velocity is greatest at the centerline r=0;the magnitude of its radial gradient is greatest at the wall r=R.')],d(r'\text{(a) }0.92593,0.69444,0\ {\rm cm/s};\quad\text{(b) }0,-92.5926,-185.1852\ {\rm s^{-1}}'),('관벽에서 v=0,중심에서 v′=0이며 속도는 바깥쪽으로 단조 감소한다. 원본 Example7의 계수 P/(4ηl)를 대조했다.','At the wall v=0;at the center v′=0;velocity decreases outward. The coefficient P/(4ηl) was checked against source Example7.'),list('abc'))
add(30,('현의 진동수 f=(1/(2L))√(T/ρ),L,T,ρ>0이다. (a)나머지 두 변수를 고정할 때 L,T,ρ 각각에 대한 변화율,(b)진동하는 길이를 줄일 때,장력을 높일 때,선밀도를 높일 때 음높이 변화를 설명하라.','A string’s frequency is f=(1/(2L))√(T/ρ),with L,T,ρ>0. (a)Find rates with respect to L,T,andρ while holding the other two fixed. (b)Describe pitch changes when vibrating length decreases,tension increases,or linear density increases.'),[same(r'\frac{\partial f}{\partial L}=-\frac1{2L^2}\sqrt{T/\rho}=-f/L'),same(r'\frac{\partial f}{\partial T}=\frac1{4L\sqrt{T\rho}}=f/(2T)'),same(r'\frac{\partial f}{\partial\rho}=-\frac{\sqrt T}{4L\rho^{3/2}}=-f/(2\rho)'),('음높이는 진동수와 함께 올라간다. 따라서 길이를 줄이면 높아지고,장력을 키워도 높아지고,선밀도를 키우면 낮아진다.','Pitch rises with frequency. Shortening the string raises pitch,increasing tension raises pitch,and increasing linear density lowers pitch.')],d(r'f_L=-f/L,\quad f_T=f/(2T),\quad f_\rho=-f/(2\rho)'),('각 도함수의 부호−,+,−를 양의 물리 매개변수 조건에서 확인했다.','Checked derivative signs−,+,− under positive physical parameters.'),list('ab'))
add(31,('청바지 x벌의 비용 C(x)=2000+3x+0.01x²+0.0002x³ 달러이다. (a)한계비용,(b)C′(100)의 값·뜻·예측,(c)101번째 벌의 정확한 추가비용과 비교하라.','The cost of x pairs of jeans is C(x)=2000+3x+0.01x²+0.0002x³ dollars. Find(a)marginal cost,(b)C′(100) with its interpretation and prediction,and(c)compare it with the exact cost of the101st pair.'),[same(r'C\prime(x)=3+0.02x+0.0006x^2'),same(r'C\prime(100)=3+2+6=11\ {\rm dollars/pair}'),('100벌 부근에서 생산을1벌 늘리는 추가비용을 약11달러로 예측한다.','Near100pairs,the derivative predicts about$11 to produce one additional pair.'),same(r'C(101)-C(100)=3+0.01(201)+0.0002(30301)=11.0702')],d(r'C\prime=3+0.02x+0.0006x^2;\quad C\prime(100)=11;\quad\Delta C_{101}=11.0702'),('정확한 추가비용은 한계비용 근사보다0.0702달러 크다. 고정비2000은 차분과 미분에서 모두 사라진다.','Exact incremental cost exceeds the marginal estimate by$0.0702. Fixed cost2000 cancels in both the difference and derivative.'),list('abc'))
add(32,('비용 C(q)=84+0.16q−0.0006q²+0.000003q³ 달러이다. (a)C′(100)을 구하고 해석하라. (b)101번째 제품의 정확한 비용과 비교하라.','Cost is C(q)=84+0.16q−0.0006q²+0.000003q³ dollars. (a)Find and interpret C′(100). (b)Compare it with the exact incremental cost of item101.'),[same(r'C\prime(q)=0.16-0.0012q+0.000009q^2'),same(r'C\prime(100)=0.16-0.12+0.09=0.13\ {\rm dollars/item}'),same(r'C(101)-C(100)=0.16-0.0006(201)+0.000003(30301)=0.130303')],d(r'C\prime(100)=0.13;\quad C(101)-C(100)=0.130303'),('한계비용은101번째 제품을 약13센트로 예측하며 정확한 값보다0.000303달러 작다.','Marginal cost predicts about13cents for item101,and is$0.000303 below the exact value.'),list('ab'))
add(33,('x명의 노동자가 만드는 총생산가치 p(x),평균생산성 A(x)=p(x)/x(x>0)에 대해(a)A′와 그 값이 양수일 때 추가 고용의 생산성 측면 의미,(b)p′가 평균생산성보다 크면 A′>0임을 설명하라.','For total production value p(x) with x workers and average productivity A(x)=p(x)/x,x>0,(a)find A′ and explain the productivity incentive when it is positive,and(b)show A′>0 if marginal productivity exceeds average productivity.'),[same(r'A\prime=\frac{xp\prime-p}{x^2}=\frac{p\prime-A}{x}'),('A′>0이면 노동자를 조금 늘릴 때 노동자당 평균 생산가치가 증가한다. 이는 생산성 관점의 추가 고용 동기이며 임금·다른 비용을 포함한 이익 판정과는 별개이다.','If A′>0,a small workforce increase raises production value per worker. This is a productivity incentive,distinct from a profit calculation including wages and other costs.'),same(r'x>0,\quad p\prime>A\Rightarrow A\prime>0')],d(r'A\prime=(xp\prime-p)/x^2=(p\prime-A)/x'),('양수 x로 나누므로 부등호가 바뀌지 않는다.','Division by positive x preserves the inequality.'),list('ab'))
add(34,('밝기 x≥0에 따른 동공 면적 R=(40+24x^0.4)/(1+4x^0.4) mm²이다. (a)민감도 S=dR/dx,(b)R,S 그래프와 낮은 밝기에서의 값·해석을 구하라.','Pupil area at brightness x≥0 is R=(40+24x^0.4)/(1+4x^0.4) mm². Find(a)sensitivity S=dR/dx,and(b)plot R,S and interpret their behavior at low brightness.'),[same(r'R=6+\frac{34}{1+4x^{2/5}}'),same(r'S=-\frac{54.4x^{-3/5}}{(1+4x^{2/5})^2}\quad(x>0)'),same(r'\lim_{x\to0^+}R=40,\quad\lim_{x\to0^+}S=-\infty'),('어두울 때 동공은 크고 작은 밝기 증가에 면적이 빠르게 줄어드는 모형이다. S의 발산은 모형의 극한 특성이며 실제 눈의 무한 민감도를 증명하지 않는다.','The model has a large pupil in darkness and a rapid area decrease for a small brightness increase. The divergence of S is a model limit,not proof of infinite physiological sensitivity.')],d(r'S=-54.4x^{-3/5}/(1+4x^{2/5})^2;\quad R(0)=40,\ S\to-\infty'),('몫 법칙과 정리식 R=6+34/(1+4x^(2/5))의 연쇄법칙을 비교했다. x=0에는 유한한 오른쪽 도함수가 없다.','Compared quotient-rule differentiation with the simplified form. There is no finite right derivative at x=0.'),list('ab'))
D.fig(34,[panel('Area R at low brightness',(0,2,0,42),[samples(lambda z:(40+24*z**.4)/(1+4*z**.4),0,2,900)],[(0,40)],xlabel='brightness x',ylabel='R (mm^2)'),panel('Sensitivity S; divergent at zero',(0,2,-120,2),[samples(lambda z:-54.4*z**(-.6)/(1+4*z**.4)**2,.00001,2,1000)],xlabel='brightness x',ylabel='S')])
add(35,('이상기체 PV=nRT에서 R=0.0821,n=10mol이다. 어느 순간 P=8atm,P′=0.10atm/min,V=10L,V′=−0.15L/min일 때 T′를 구하라.','For the ideal-gas law PV=nRT with R=0.0821 and n=10mol,find T′ when P=8atm,P′=0.10atm/min,V=10L,V′=−0.15L/min.'),[same(r'P\prime V+PV\prime=nRT\prime'),same(r'T\prime=\frac{(0.10)(10)+8(-0.15)}{10(0.0821)}=\frac{-0.2}{0.821}\approx-0.243605')],d(r'T\prime\approx-0.2436\ {\rm K/min}'),('PV의 순변화율은1−1.2=−0.2atm·L/min이므로 온도는 감소한다.','The net PV rate is1−1.2=−0.2atm·L/min,so temperature decreases.'))
add(36,('번식률 r>0,분산 상수 D>0에 따른 침입종 확산 전선의 속도 f(r)=2√(Dr)의 도함수를 구하고 뜻을 설명하라.','The invasion-front speed is f(r)=2√(Dr),where reproductive rate r>0 and dispersal parameter D>0. Find and interpret its derivative.'),[same(r'f\prime(r)=2\cdot\frac{D}{2\sqrt{Dr}}=\sqrt{D/r}'),('번식률이 Δr만큼 조금 늘면 확산 속도는 약√(D/r)Δr 늘어난다. 변화율은 양수이지만 r이 커질수록 작아진다.','A small increase Δr raises wave speed by about√(D/r)Δr. The rate is positive but decreases as r increases.')],d(r'f\prime(r)=\sqrt{D/r}'),('D는 고정한 채 미분했다. f″=−√D/(2r^(3/2))<0이므로 한계 효과가 감소한다.','Differentiated with D fixed. Since f″=−√D/(2r^(3/2))<0,the marginal effect decreases.'))
add(37,('순록 C,늑대 W의 모형 C′=aC−bCW,W′=−cW+dCW에 대해 (a)일정 개체군의 도함수 조건,(b)순록 멸종의 수학적 표현,(c)a=.05,b=.001,c=.05,d=.0001에서 모든 비음수 평형(C,W)와 공존 가능성을 구하라.','For caribou C and wolves W modeled by C′=aC−bCW,W′=−cW+dCW,find(a)derivative conditions for constant populations,(b)a mathematical statement of caribou extinction,and(c)all nonnegative equilibria for a=.05,b=.001,c=.05,d=.0001 and whether coexistence is possible.'),[same(r'\text{(a) }C\prime=W\prime=0'),same(r'\text{(b) }C=0\ \text{(extinct state)},\quad\lim_{t\to\infty}C(t)=0\ \text{(eventual extinction)}'),same(r'C(0.05-0.001W)=0,\quad W(-0.05+0.0001C)=0'),same(r'(C,W)=(0,0)\quad\text{or}\quad(C,W)=(500,50)'),('양의 평형은 순록500,늑대50이므로 이 모형에는 두 종이 일정하게 공존하는 상태가 있다. 모든 초기조건이 그 평형으로 수렴한다는 뜻은 아니다.','The positive equilibrium has500caribou and50wolves,so constant coexistence is possible in the model. This does not mean every initial condition converges to it.')],d(r'\text{Equilibria: }(0,0),(500,50)'),('두 평형을 각각 두 미분방정식에 대입하면0이다. 한 종만 양수인 일정 상태는 방정식을 만족하지 않는다.','Both pairs make both derivatives zero. No equilibrium with exactly one positive population satisfies the equations.'),list('abc'))
add(38,('기억 유지율 R(t)=a+b(1+ct)^(-β),0<a,b,c<1,β>0,R(0)=1이며 t는학습후 일수이다. (a)변화율,(b)학습 직후와 오래 지난 뒤 중 더 빨리 잊는 때,(c)영구 유지 비율을 구하라.','Memory retention is R(t)=a+b(1+ct)^(-β),with0<a,b,c<1,β>0,R(0)=1,and t in days after learning. Find(a)its rate,(b)whether forgetting is faster soon after learning or much later,and(c)the permanent fraction.'),[same(r'R\prime=-bc\beta(1+ct)^{-\beta-1}'),same(r'|R\prime|=bc\beta(1+ct)^{-\beta-1}\ \text{decreases as }t\text{ increases}'),same(r'R(0)=a+b=1,\quad\lim_{t\to\infty}R(t)=a')],('(a)−bcβ(1+ct)^(−β−1)/일;(b)학습 직후;(c)a.','(a)−bcβ(1+ct)^(−β−1) per day;(b)soon after learning;(c)a.'),('R′<0,R″=bc²β(β+1)(1+ct)^(−β−2)>0이므로 감소하면서 감소 속력은 작아진다.','R′<0 and R″=bc²β(β+1)(1+ct)^(−β−2)>0,so retention decreases while the rate of loss slows.'),list('abc'))
